{"code":"import pandas as pd, statsmodels.formula.api as smf
x=pd.read_csv('data/explore.csv'); ex=['nitrogen_ppm','phosphorus_ppm','potassium_ppm','soil_ph','irrigation_mm','seed_density','mulch_depth_cm','biochar_g','fungicide_ml','shade_pct']
for e in ex:
 d=x[['yield_kg','farm',e]].dropna(); m=smf.ols(f'yield_kg ~ {e} + C(farm)',d).fit(); print(e, len(d), round(m.params[e],3),round(m.pvalues[e],5),round(m.rsquared,3))"}
